@ void keccak_f1600_x1_armv7m_asm( void *state, const uint32_t *rc )
@
.align 8
.global   MLD_ASM_NAMESPACE(keccak_f1600_x1_armv7m_asm)
.type MLD_ASM_NAMESPACE(keccak_f1600_x1_armv7m_asm),%function
MLD_ASM_FN_SYMBOL(keccak_f1600_x1_armv7m_asm)
    push    { r4 - r12, lr }
    sub     sp, #mSize
    str     r1, [sp, #mRC]
keccak_f1600_x1_armv7m_asm_KeccakF1600_StatePermute_RoundLoop:
        keccak_f1600_x1_armv7m_slothy_start_round0:
                                          // Instructions:    413
                                          // Expected cycles: 207
                                          // Expected IPC:    2.00
                                          //
                                          // ---------------------------------------------------------------------------------------------- cycle (expected) ---------------------------------------------------------------------------------------------->
                                          // 0                        25                       50                       75                       100                      125                      150                      175                      200
                                          // |------------------------|------------------------|------------------------|------------------------|------------------------|------------------------|------------------------|------------------------|------
        ldr r8, [r0, #12]                 // *.............................................................................................................................................................................................................. // @slothy:reads=['r0Abe1']
        ldr r5, [r0, #32]                 // *.............................................................................................................................................................................................................. // @slothy:reads=['r0Abu0']
        ldr r2, [r0, #72]                 // .*............................................................................................................................................................................................................. // @slothy:reads=['r0Agu0']
        ldr r12, [r0, #36]                // .*............................................................................................................................................................................................................. // @slothy:reads=['r0Abu1']
        eors r1, r5, r2                   // ..*............................................................................................................................................................................................................
        ldr r9, [r0, #52]                 // ..*............................................................................................................................................................................................................ // @slothy:reads=['r0Age1']
        ldr r2, [r0, #92]                 // ...*........................................................................................................................................................................................................... // @slothy:reads=['r0Ake1']
